import { useEffect } from 'react';
import { useMigrations } from 'drizzle-orm/expo-sqlite/migrator';
import { db, getRawDb } from './client';
// Generated by `npm run db:generate` (drizzle-kit). See migrations.d.ts.
import migrations from './migrations/migrations';

/**
 * Applies pending SQLite migrations at startup.
 * Returns { success, error } — the root layout gates rendering on success.
 *
 * Foreign-key enforcement is disabled while migrations run and re-enabled
 * after: a future table-rebuild migration (DROP TABLE after copying) would
 * otherwise fire ON DELETE CASCADE and wipe user data. Our migrations never
 * depend on FK enforcement, so this is safe.
 */
export function useDrizzleMigrations() {
  useEffect(() => {
    getRawDb().execSync('PRAGMA foreign_keys = OFF');
    return () => {
      getRawDb().execSync('PRAGMA foreign_keys = ON');
    };
  }, []);
  const result = useMigrations(db, migrations);
  useEffect(() => {
    if (result.success) {
      // A table-rebuild migration that left dangling references would only
      // fail on a later unrelated write — detect it here instead.
      const violations = getRawDb().getAllSync('PRAGMA foreign_key_check');
      if (violations.length > 0) {
        console.warn('[lift] foreign_key_check found violations after migration:', violations);
      }
      getRawDb().execSync('PRAGMA foreign_keys = ON');
    }
  }, [result.success]);
  return result;
}
